// autogeneratedPrimaryKeyBySequence draws the primary key from a named DB
// sequence (typed only on mariaDB / oracle / postgreSql / sqlServer), distinct
// from the autogenerated IDENTITY/SERIAL PK the engine fills implicitly. The
// emitted INSERT references the sequence's next-value (the exact form is
// per-dialect, pinned by the snapshot). SQLite and MySQL don't expose the
// method (their connection types omit it), so the test is NOT-APPLICABLE there
// with a paired compile-time negative in the dialect's types.negative/ folder.

import { afterAll, beforeAll, beforeEach, describe, expect, test } from '../../../../lib/testRunner.js'
import { assertType, type Exact } from '../../../../lib/assertType.js'
import { tAuditEntry, tAuditEntryNoAdapter, tInvoice, tIssue } from '../../domain/connection.js'
import { ctx } from './setup.js'

describe(ctx.label, () => {
    beforeAll(() => ctx.up(), ctx.timeoutMs)
    afterAll(() => ctx.down(), ctx.timeoutMs)
    beforeEach(() => { ctx.reset() })

    test('insert-with-sequence-primary-key-references-the-sequence', async () => {
        // The PK value comes from the sequence, so the INSERT references its
        // next-value rather than relying on an IDENTITY/SERIAL default. A
        // committing transaction + reseed is used because the sequence bump is
        // non-transactional (a rollback would leave the counter advanced).
        //
        // tAuditEntry.id carries the autogeneratedPrimaryKeyBySequence
        // TRAILING TypeAdapter overload (plusOffsetAdapter, read +1000). The
        // emitted INSERT/RETURNING SQL is unchanged by the adapter (it only
        // transforms the read), so the returned id surfaces OFFSET: the mock
        // queues the raw DB id 50, which the adapter reads back as 1050; on a real
        // DB the id is the raw sequence value (>= 1) + 1000, so id >= 1001.
        await ctx.withCommit(async () => {
            ctx.mockNext(50)
            const id = await ctx.conn.insertInto(tAuditEntry)
                .values({ action: 'archived' })
                .returningLastInsertedId()
                .executeInsert()

            expect(ctx.lastSql).toMatchInlineSnapshot(`"insert into audit_entry (id, action) values (audit_tag_seq.nextval, :0) returning id into :1"`)
            expect(ctx.lastParams).toMatchInlineSnapshot(`
              [
                "archived",
                {
                  "dir": 3003,
                },
              ]
            `)
            assertType<Exact<typeof id, number>>()
            if (!ctx.realDbEnabled) expect(id).toBe(1050)
            else expect(id).toBeGreaterThanOrEqual(1001)
        })
    })

    test('insert-with-explicit-sequence-next-value-as-a-column-value', async () => {
        // `issueIdSeq.nextValue()` passed directly as an INSERT column value emits
        // the raw sequence next-value in the VALUES list (no bound param), so
        // tInvoice's invoice_no scaledTenthAdapter never fires — the column receives
        // the raw sequence value. withCommit + reseed because the sequence bump is
        // non-transactional.
        await ctx.withCommit(async () => {
            ctx.mockNext(1)
            const affected = await ctx.conn.insertInto(tInvoice)
                .values({ invoiceNo: ctx.conn.issueIdSeq.nextValue(), total: 1200 })
                .executeInsert()

            expect(ctx.lastSql).toMatchInlineSnapshot(`"insert into invoice (invoice_no, total) values (issue_id_seq.nextval, :0)"`)
            expect(ctx.lastParams).toMatchInlineSnapshot(`
              [
                1200,
              ]
            `)
            assertType<Exact<typeof affected, number>>()
            if (!ctx.realDbEnabled) expect(affected).toBe(1)
            else expect(typeof affected).toBe('number')
        })
    })

    test('insert-with-no-adapter-sequence-primary-key-returns-the-raw-sequence-value', async () => {
        // The NO-ADAPTER autogeneratedPrimaryKeyBySequence overload
        // (tAuditEntryNoAdapter): the DB-generated id surfaces RAW, in contrast to
        // tAuditEntry above whose id carries plusOffsetAdapter (read +1000). Both map
        // to the same audit_entry table + audit_tag_seq sequence, so the emitted
        // INSERT/RETURNING SQL is identical — only the read differs. The mock queues
        // the raw id 50, read back unchanged as 50 (tAuditEntry would read 1050); on a
        // real DB the id is the raw sequence value, >= 1. withCommit + reseed because
        // the sequence bump is non-transactional.
        await ctx.withCommit(async () => {
            ctx.mockNext(50)
            const id = await ctx.conn.insertInto(tAuditEntryNoAdapter)
                .values({ action: 'purged' })
                .returningLastInsertedId()
                .executeInsert()

            expect(ctx.lastSql).toMatchInlineSnapshot(`"insert into audit_entry (id, action) values (audit_tag_seq.nextval, :0) returning id into :1"`)
            expect(ctx.lastParams).toMatchInlineSnapshot(`
              [
                "purged",
                {
                  "dir": 3003,
                },
              ]
            `)
            assertType<Exact<typeof id, number>>()
            if (!ctx.realDbEnabled) expect(id).toBe(50)
            else expect(id).toBeGreaterThanOrEqual(1)
        })
    })

    test('insert-multiple-rows-on-a-sequence-primary-key', async () => {
        // Multi-row INSERT walks a different builder path from the single-row
        // one: the sequence column has to be re-emitted per VALUES tuple
        // rather than once. A committing transaction + reseed is used because
        // the sequence bump is non-transactional.
        await ctx.withCommit(async () => {
            ctx.mockNext(2)
            const count = await ctx.conn.insertInto(tAuditEntry)
                .values([{ action: 'archived' }, { action: 'restored' }])
                .executeInsert()

            expect(ctx.lastSql).toMatchInlineSnapshot(`"begin insert into audit_entry (id, action) values (audit_tag_seq.nextval, :0); insert into audit_entry (id, action) values (audit_tag_seq.nextval, :1); end;"`)
            expect(ctx.lastParams).toMatchInlineSnapshot(`
              [
                "archived",
                "restored",
              ]
            `)
            assertType<Exact<typeof count, number>>()
            expect(count).toEqual(2)
        })
    })

    test('insert-omitting-the-sequence-column-from-the-set-emits-the-next-sequence-value-unless-supplied', async () => {
        // The sequence-backed primary key is omitted from `set(...)`: it is filled
        // with the sequence's next-value, so the emitted column list still names it
        // and only `action` rides as a bound param. Supplying that key IS
        // type-permitted — an autogenerated primary key is an OPTIONAL key of the
        // set object — and the second insert is that contrast: the supplied value
        // takes the place of the next-value in the VALUES list. tAuditEntry.id
        // carries an offset adapter that writes -1000, so the logical id 1900 binds
        // as the raw 900. audit_entry has no seeded rows, so neither id collides,
        // and both are rolled back.
        await ctx.withRollback(async () => {
            ctx.mockNext(1)
            const affectedFromSequence = await ctx.conn.insertInto(tAuditEntry)
                .set({ action: 'exported' })
                .executeInsert()

            expect(ctx.lastSql).toMatchInlineSnapshot(`"insert into audit_entry (id, action) values (audit_tag_seq.nextval, :0)"`)
            expect(ctx.lastParams).toMatchInlineSnapshot(`
              [
                "exported",
              ]
            `)
            assertType<Exact<typeof affectedFromSequence, number>>()
            expect(affectedFromSequence).toBe(1)

            ctx.mockNext(1)
            const affectedWithSuppliedId = await ctx.conn.insertInto(tAuditEntry)
                .set({ id: 1900, action: 'exported-with-explicit-id' })
                .executeInsert()

            expect(ctx.lastSql).toMatchInlineSnapshot(`"insert into audit_entry (id, action) values (:0, :1)"`)
            expect(ctx.lastParams).toMatchInlineSnapshot(`
              [
                900,
                "exported-with-explicit-id",
              ]
            `)
            assertType<Exact<typeof affectedWithSuppliedId, number>>()
            expect(affectedWithSuppliedId).toBe(1)
        })
    })

    test('insert-from-select-into-a-sequence-primary-key-emits-the-sequence-in-the-column-list', async () => {
        // INSERT ... SELECT into a table whose primary key comes from a sequence:
        // the sequence column is absent from the projected select, so it is added
        // to the INSERT column list with its next-value projected as the matching
        // select item — one sequence value per source row. The source is every
        // issue of project 1 (issues 1 and 2 in the seed), so exactly two audit
        // rows are inserted and rolled back.
        //
        // Rollback is enough here, unlike the committing tests above: none of the
        // three tests appended below asserts an exact `audit_tag_seq` value, so the
        // sequence advancing outside the transaction is harmless.
        await ctx.withRollback(async () => {
            ctx.mockNext(2)
            const inserted = await ctx.conn.insertInto(tAuditEntry)
                .from(ctx.conn.selectFrom(tIssue)
                    .where(tIssue.projectId.equals(1))
                    .select({ action: tIssue.status }))
                .executeInsert()

            expect(ctx.lastSql).toMatchInlineSnapshot(`"insert into audit_entry (action, id) select status as "action", audit_tag_seq.nextval as "id" from issue where project_id = :0"`)
            expect(ctx.lastParams).toMatchInlineSnapshot(`
              [
                1,
              ]
            `)
            assertType<Exact<typeof inserted, number>>()
            expect(inserted).toBe(2)

            // The count alone would not pin WHICH column fed `action`; reading the
            // two rows back does. Ordered by value so the result is stable.
            ctx.mockNext(['in_progress', 'open'])
            const actions = await ctx.conn.selectFrom(tAuditEntry)
                .selectOneColumn(tAuditEntry.action)
                .orderBy('result')
                .executeSelectMany()

            expect(ctx.lastSql).toMatchInlineSnapshot(`"select action as "result" from audit_entry order by "result""`)
            expect(ctx.lastParams).toMatchInlineSnapshot(`[]`)
            assertType<Exact<typeof actions, string[]>>()
            expect(actions).toEqual(['in_progress', 'open'])
        })
    })

    test('insert-shaped-as-on-a-sequence-primary-key-emits-the-sequence-with-the-renamed-column', async () => {
        // `shapedAs({ statusLabel: 'action' })` renames the value key the caller
        // supplies. The sequence-backed primary key is not part of the shape, so
        // its next-value is still emitted ahead of the renamed column: a shape
        // renames what is supplied, it does not suppress the sequence.
        // tAuditEntryNoAdapter maps audit_entry with no adapter on the id, so the
        // single bound param is the action string verbatim.
        await ctx.withRollback(async () => {
            ctx.mockNext(1)
            const affected = await ctx.conn.insertInto(tAuditEntryNoAdapter)
                .shapedAs({ statusLabel: 'action' })
                .set({ statusLabel: 'shaped-export' })
                .executeInsert()

            expect(ctx.lastSql).toMatchInlineSnapshot(`"insert into audit_entry (id, action) values (audit_tag_seq.nextval, :0)"`)
            expect(ctx.lastParams).toMatchInlineSnapshot(`
              [
                "shaped-export",
              ]
            `)
            assertType<Exact<typeof affected, number>>()
            expect(affected).toBe(1)
        })
    })
})
